class Solution { public:vector<int> smallestTrimmedNumbers(vector<string>& nums,vector<vector<int>>& queries){vector<int> answer;int length=nums[0].size();for(auto& query:queries){int trim=query[1];vector<int> indices(nums.size());iota(indices.begin(),indices.end(),0);sort(indices.begin(),indices.end(),[&](int a,int b){string first=nums[a].substr(length-trim),second=nums[b].substr(length-trim);return first==second?a<b:first<second;});answer.push_back(indices[query[0]-1]);}return answer;} };
